<script setup>
import { computed, onMounted, ref } from 'vue'
import { api } from '../../api/client'
import { date, duration } from '../reports/presentation'
const projects = ref([]), query = ref(''), loading = ref(true), error = ref('')
const visible = computed(() => projects.value.filter(p => `${p.title} ${p.scenario_title}`.toLowerCase().includes(query.value.trim().toLowerCase())))
onMounted(async () => { try { projects.value = await api('/projects') } catch (e) { error.value = e.message } finally { loading.value = false } })
</script>
<template><main class="page"><div class="page-heading"><div><h1>평가 프로젝트</h1><p class="muted">함께 일하는 과정을 관찰하고, 지원자별 근거를 확인하세요.</p></div><RouterLink class="primary" to="/projects/new">＋ 프로젝트 만들기</RouterLink></div><p v-if="error" class="error" role="alert">{{ error }}</p><div class="list-toolbar"><input v-model="query" class="search-field" aria-label="프로젝트 검색" placeholder="프로젝트 이름 또는 시나리오 검색"><span class="muted">전체 {{ projects.length }}개 프로젝트</span></div><p v-if="loading" role="status" class="muted">프로젝트를 불러오고 있습니다…</p><div v-else-if="!projects.length && !error" class="card empty-state"><span class="empty-symbol">＋</span><h2>첫 번째 프로젝트를 만들어 보세요</h2><p class="muted">역량 선택부터 개인별 근거 리포트까지, 한곳에서 관리합니다.</p><RouterLink class="text-button" to="/projects/new">프로젝트 만들기 →</RouterLink></div><p v-else-if="!visible.length && !error" class="empty-note">검색 조건에 맞는 프로젝트가 없습니다.</p><div class="project-grid"><RouterLink v-for="p in visible" :key="p.id" :to="`/projects/${p.id}`" class="card project-card"><div class="review-heading"><span class="badge" :class="{ amber: p.is_fixture }">{{ p.is_fixture ? '개발용 · 실제 평가 아님' : '평가 프로젝트' }}</span><small class="muted">{{ date(p.created_at) }}</small></div><h2>{{ p.title }}</h2><p class="muted">{{ p.scenario_title }} · {{ duration(p.duration_seconds) }}</p><div class="chips"><span v-for="c in p.competencies" :key="c.id" class="badge">{{ c.name }}</span></div><div class="project-counts"><span>초대 <strong>{{ p.counts?.invited ?? '—' }}</strong></span><span>응시 완료 <strong>{{ p.counts?.submitted ?? '—' }}</strong></span><span>리포트 <strong>{{ p.counts?.reports_ready ?? '—' }}</strong></span><span class="manage-link">관리 →</span></div></RouterLink></div></main></template>
